  /** Each period's due-total by its id. */
  readonly dueTotals = input.required<Map<number, string>>();
  /** A period added through the form, or closed, reopened, locked or unlocked from its row. */
  readonly saved = output<Period>();

  protected readonly error = signal('');
  /** The refusal of the last action taken on a period's row, shown on that row. */
  protected readonly periodError = signal<{ id: number; message: string } | null>(null);
  /** Whether a submit is waiting for its answer: a second submit meanwhile is ignored. */
  private submitting = false;
  protected readonly form = new FormGroup({
    name: new FormControl('', { nonNullable: true }),
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
    cap: new FormControl('', { nonNullable: true }),
  });

  protected readonly generateError = signal('');
  /** How many periods the last generate made; null while one runs or before the first. */
  protected readonly generated = signal<number | null>(null);
  private generating = false;
  protected readonly generateForm = new FormGroup({
    from: new FormControl('', { nonNullable: true }),
    to: new FormControl('', { nonNullable: true }),
    year: new FormControl('', { nonNullable: true }),
    quartersYear: new FormControl('', { nonNullable: true }),
  });

  protected readonly rolloverError = signal('');
  /** How many periods the last rollover made; null while one runs or before the first. */
  protected readonly rolledOver = signal<number | null>(null);
  private rollingOver = false;
  protected readonly rolloverForm = new FormGroup({
    year: new FormControl('', { nonNullable: true }),
  });

  protected readonly openingError = signal('');
  /** How many lines the last opening balances paste put through; null while one runs or before the first. */
  protected readonly openingsDone = signal<number | null>(null);
  private importing = false;
  protected readonly openingForm = new FormGroup({
    text: new FormControl('', { nonNullable: true }),
  });

  constructor() {
    this.form.valueChanges.subscribe(() => this.error.set(''));
    this.openingForm.valueChanges.subscribe(() => this.openingError.set(''));
    this.generateForm.valueChanges.subscribe(() => this.generateError.set(''));
    this.rolloverForm.valueChanges.subscribe(() => this.rolloverError.set(''));
  }

  protected async generate(): Promise<void> {
    if (this.generating) return;
    this.generateError.set('');
    this.generated.set(null);
    const from = this.generateForm.getRawValue().from.trim();
    const to = this.generateForm.getRawValue().to.trim();
    if ((from && !DAY.test(from)) || !DAY.test(to)) {
      this.generateError.set('Enter the day to generate to.');
      return;
    }
    if (from && to < from) {
      this.generateError.set('The to-date cannot be before the from-date.');
      return;
    }
    this.generating = true;
    try {
      const made = await this.api.generate(from, to);
      for (const p of made) this.saved.emit(p);
      this.generated.set(made.length);
    } catch {
      this.generateError.set('The periods could not be generated.');
    } finally {
      this.generating = false;
    }
  }

  /** Generate the twelve monthly periods of the fiscal year typed. */
  protected async generateFy(): Promise<void> {
    if (this.generating) return;
    this.generateError.set('');
    this.generated.set(null);
    const year = this.generateForm.getRawValue().year.trim();
    if (!/^\d{4}$/.test(year)) {
      this.generateError.set('Enter the fiscal year (yyyy) to generate.');
      return;
    }
    this.generating = true;
    try {
      const made = await this.api.generateFy(year);
      for (const p of made) this.saved.emit(p);
      this.generated.set(made.length);
    } catch {
      this.generateError.set('The fiscal year could not be generated.');
    } finally {
      this.generating = false;
    }
  }

  /** Generate the four calendar quarters of the year typed. */
  protected async generateQuarters(): Promise<void> {
    if (this.generating) return;
    this.generateError.set('');
    this.generated.set(null);
    const year = this.generateForm.getRawValue().quartersYear.trim();
    if (!/^\d{4}$/.test(year)) {
      this.generateError.set('Enter the calendar year (yyyy) to generate quarters for.');
      return;
    }
    this.generating = true;
    try {
      const made = await this.api.generateQuarters(year);
      for (const p of made) this.saved.emit(p);
      this.generated.set(made.length);
    } catch {
      this.generateError.set('The quarters could not be generated.');
    } finally {
      this.generating = false;
    }
  }

  /** Roll the fiscal year typed over into the next one. */
  protected async rollover(): Promise<void> {
    if (this.rollingOver) return;
    this.rolloverError.set('');
    this.rolledOver.set(null);
    const year = this.rolloverForm.getRawValue().year.trim();
    if (!/^\d{4}$/.test(year)) {
      this.rolloverError.set('Enter the fiscal year (yyyy) to roll over.');
      return;
    }
    this.rollingOver = true;
    try {
      const done = await this.api.rollover(year);
      for (const p of done.periods) this.saved.emit(p);
      this.rolledOver.set(done.made);
    } catch (e) {
      this.rolloverError.set(
        e instanceof HttpErrorResponse && e.status === 403
          ? 'Only a steward may roll a year over.'
          : 'The year could not be rolled over: it has no periods.',
      );
    } finally {
      this.rollingOver = false;
    }
  }

  /** Paste the opening balances typed: every line is checked first, so any error refuses them all. */
  protected async importOpenings(): Promise<void> {
    if (this.importing) return;
    this.openingError.set('');
    this.openingsDone.set(null);
    const text = this.openingForm.getRawValue().text;
    if (!text.trim()) {
      this.openingError.set('Paste at least one line of name,period,amount.');
      return;
    }
    this.importing = true;
    try {
      const imported = await this.api.importOpenings(text);
      for (const p of imported.periods) this.saved.emit(p);
      this.openingsDone.set(imported.added);
    } catch (e) {
      this.openingError.set(
        e instanceof HttpErrorResponse && typeof e.error?.message === 'string' && e.error.message.startsWith('Line ')
          ? e.error.message
          : 'The opening balances could not be pasted.',
      );
    } finally {
      this.importing = false;
    }
  }

  protected async close(p: Period): Promise<void> {
    this.periodError.set(null);
    try {
      this.saved.emit(await this.api.close(p.id));
    } catch {
      this.periodError.set({ id: p.id, message: 'The period could not be closed.' });
    }
  }

  protected async softClose(p: Period): Promise<void> {
    this.periodError.set(null);
    try {
      this.saved.emit(await this.api.softClose(p.id));
    } catch {
      this.periodError.set({ id: p.id, message: 'The period could not be soft-closed.' });
    }
  }

  protected async reopen(p: Period): Promise<void> {
    this.periodError.set(null);
    try {
      this.saved.emit(await this.api.reopen(p.id));
    } catch (e) {
      this.periodError.set({
        id: p.id,
        message:
          e instanceof HttpErrorResponse && e.status === 403
            ? 'Only a steward may reopen a period.'
            : e instanceof HttpErrorResponse && e.status === 409 && p.locked
              ? 'A locked period cannot be reopened.'
              : 'The period could not be reopened.',
      });
    }
  }

  protected async setLocked(p: Period, lock: boolean): Promise<void> {
    this.periodError.set(null);
    const verb = lock ? 'lock' : 'unlock';
    try {
      this.saved.emit(await this.api.setLocked(p.id, lock));
    } catch (e) {
      this.periodError.set({
        id: p.id,
        message:
          e instanceof HttpErrorResponse && e.status === 403
            ? `Only a steward may ${verb} a period.`
            : lock ? 'The period is already locked.' : 'The period is not locked.',
      });
    }
  }

  protected async submit(): Promise<void> {
    if (this.submitting) return;
    this.error.set('');
    const { name, from, to, cap } = this.form.getRawValue();
    if (!name.trim()) {
      this.error.set('Enter a name.');
      return;
    }
    if (!DAY.test(from.trim()) || !DAY.test(to.trim())) {
      this.error.set('Enter the day the period runs from and the day it runs to.');
      return;
    }
    if (to.trim() < from.trim()) {
      this.error.set('A period cannot end before it starts.');
      return;
    }
    if (cap.trim() && !(/^\d+$/.test(cap.trim()) && Number(cap.trim()) >= 1)) {
      this.error.set('The cap must be a whole number of 1 or more, or blank for none.');
      return;
    }
    this.submitting = true;
    try {
      this.saved.emit(
        await this.api.add({
          name: name.trim(),
          from: from.trim(),
          to: to.trim(),
          cap: cap.trim() ? Number(cap.trim()) : null,
        }),
      );
      this.form.reset({ name: '', from: '', to: '', cap: '' }, { emitEvent: false });
    } catch (e) {
      this.error.set(
        e instanceof HttpErrorResponse && e.status === 409
          ? 'That name is in use, or the period overlaps another on this sheet.'
          : 'The period could not be added.',
      );
    } finally {
      this.submitting = false;
    }
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { firstValueFrom } from 'rxjs';
import { Pools } from './pools';
import { Session } from './session';

export interface Period {
  id: number;
  /** Unique on the sheet. */
  name: string;
  /** The first day (yyyy-mm-dd) of the period. */
  from: string;
  /** The last day (yyyy-mm-dd) of the period. */
  to: string;
  /** Whether the period is closed: no claim dated inside it can be changed. */
  closed: boolean;
  /** Whether the period is soft-closed: its due-totals are fixed as for a closed one, but claims
   *  dated inside it can still be changed. */
  softClosed: boolean;
  /** The due-total fixed when it was closed or soft-closed, as text with two decimals; null while it is open. */
  closedTotal: string | null;
  /** Each person's due-total for the period fixed when it was closed, by the person's id, as text
   *  with two decimals; empty while it is open. A person missing from it has 0.00. */
  closedPersonTotals: Record<number, string>;
  /** Each person's carried figure for the period fixed when it was closed or soft-closed, by the
   *  person's id, as text with two decimals; empty while it is open. A person missing from it has 0.00. */
  closedPersonCarried: Record<number, string>;
  /** Each person's opening balance for the period, by the person's id, as text with two decimals:
   *  added to their carried figure for it. A person missing from it has 0.00. */
  personOpenings: Record<number, string>;
  /** The fiscal year its from-date falls in (FYyyyy). */
  fy: string;
  /** The most open or pending claims a person may have in the period; null for no cap. */
  cap: number | null;
  /** Whether a steward has locked the period: a locked period cannot be reopened. */
  locked: boolean;
}

export interface PeriodForm {
  name: string;
  from: string;
  to: string;
  /** The most open or pending claims a person may have in the period (1 or more); null for no cap. */
  cap: number | null;
}

/** The period whose days contain the day, or undefined when there is none. */
export function periodOf(periods: Period[], day: string): Period | undefined {
  return periods.find((p) => p.from <= day && day <= p.to);
}

// The periods on the active sheet.
@Injectable({ providedIn: 'root' })
export class Periods {
  private readonly http = inject(HttpClient);
  private readonly session = inject(Session);
  private readonly pools = inject(Pools);

  /** The periods on the sheet, earliest first. */
  list(sheetId: string): Promise<Period[]> {
    return firstValueFrom(this.http.get<Period[]>(this.url(sheetId)));
  }

  /** Add a period; refused when it ends before it starts, its name is in use or it overlaps another. */
  add(form: PeriodForm): Promise<Period> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(this.http.post<Period>(this.url(sheetId), form, { headers: { 'X-User': user } }));
  }

  /** Generate one period per calendar month from the from-date's month to the to-date's month,
   *  leaving out a month whose name is in use or that overlaps a period; the from-date is the
   *  sheet's today when blank. Refused when the to-date is before the from-date. */
  generate(from: string, to: string): Promise<Period[]> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<Period[]>(`${this.url(sheetId)}/generate`, { from: from || null, to },
        { headers: { 'X-User': user } }),
    );
  }

  /** Generate the twelve monthly periods of the fiscal year named by the year (yyyy), as
   *  {@link generate} does. */
  generateFy(year: string): Promise<Period[]> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<Period[]>(`${this.url(sheetId)}/generate-fy`, { year }, { headers: { 'X-User': user } }),
    );
  }

  /** Generate the four calendar quarters of the year (yyyy) as periods named yyyy-Q1 to yyyy-Q4,
   *  leaving out a quarter whose name is in use or that overlaps a period. */
  generateQuarters(year: string): Promise<Period[]> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<Period[]>(`${this.url(sheetId)}/generate-quarters`, { year }, { headers: { 'X-User': user } }),
    );
  }

  /** Roll the fiscal year (yyyy) over: generate the next fiscal year's periods as {@link generateFy}
   *  does and carry each person's open figure at the old year's end into the new year's first
   *  period. Refused when the user is not a steward or the year has no periods. Gives how many
   *  periods it made and the periods changed. */
  rollover(year: string): Promise<{ made: number; periods: Period[] }> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<{ made: number; periods: Period[] }>(`${this.url(sheetId)}/rollover`, { year },
        { headers: { 'X-User': user } }),
    );
  }

  /** Paste opening balances, lines of name,period,amount, each adding the amount to the person's
   *  carried figure for the period; all lines are checked first and any error refuses the whole
   *  paste. Gives how many lines went through and the periods changed. */
  importOpenings(text: string): Promise<{ added: number; periods: Period[] }> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<{ added: number; periods: Period[] }>(`${this.url(sheetId)}/openings`, { text },
        { headers: { 'X-User': user } }),
    );
  }

  /** Close a period, fixing its due-total; refused when it is already closed. */
  close(id: number): Promise<Period> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    // the pools' per-period cuts are fixed (or live again) with it
    return firstValueFrom(
      this.http.post<Period>(`${this.url(sheetId)}/${id}/close`, null, { headers: { 'X-User': user } }),
    ).then(async (period) => {
      await this.pools.refresh();
      return period;
    });
  }

  /** Soft-close a period, fixing its due-totals while its claims stay open to change; refused when
   *  it is already closed or soft-closed. */
  softClose(id: number): Promise<Period> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    // the pools' per-period cuts are fixed (or live again) with it
    return firstValueFrom(
      this.http.post<Period>(`${this.url(sheetId)}/${id}/soft-close`, null, { headers: { 'X-User': user } }),
    ).then(async (period) => {
      await this.pools.refresh();
      return period;
    });
  }

  /** Reopen a closed or soft-closed period, making its due-total live again; refused when the user is not a
   *  steward or the period is not closed. */
  reopen(id: number): Promise<Period> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    // the pools' per-period cuts are fixed (or live again) with it
    return firstValueFrom(
      this.http.post<Period>(`${this.url(sheetId)}/${id}/reopen`, null, { headers: { 'X-User': user } }),
    ).then(async (period) => {
      await this.pools.refresh();
      return period;
    });
  }

  /** Lock or unlock a period; refused when the user is not a steward, or it is already locked (or,
   *  to unlock, not locked). */
  setLocked(id: number, lock: boolean): Promise<Period> {
    const sheetId = this.session.sheetId();
    const user = this.session.user();
    if (!sheetId || !user) throw new Error('no sheet loaded');
    return firstValueFrom(
      this.http.post<Period>(`${this.url(sheetId)}/${id}/${lock ? 'lock' : 'unlock'}`, null,
        { headers: { 'X-User': user } }),
    );
  }

  private url(sheetId: string): string {
    return `/api/sheets/${encodeURIComponent(sheetId)}/periods`;
  }
}

