# Spring Boot host config. H2 in-memory in the same JVM; Flyway migrates the schema up on boot from
# db/migration; Actuator health is the readiness probe.

# In-memory H2 (dies with the JVM = clean per-run reset).
spring.datasource.url=jdbc:h2:mem:officehq;DB_CLOSE_DELAY=-1
spring.datasource.driver-class-name=org.h2.Driver
spring.datasource.username=sa
spring.datasource.password=
# Pooled connections are never retired: when HikariCP closes one at its default 30 min
# max-lifetime, this in-memory H2 closes under the remaining sessions and every later statement
# fails with "The database has been closed" while the health probe stays UP. 0 means no lifetime.
spring.datasource.hikari.max-lifetime=0

# Flyway owns the schema. JPA does not create tables.
spring.flyway.enabled=true
spring.jpa.hibernate.ddl-auto=none
# Close the persistence context at the end of the request, not during view rendering.
spring.jpa.open-in-view=false

# Readiness probe.
management.endpoints.web.exposure.include=health
management.endpoint.health.probes.enabled=true

# The SPA is served from src/main/resources/static (built there by bin/build); deep-link
# fallback is in SpaConfig.java.

# Audit sink: one record per line to this known file, so tests assert side-effects by reading it.
# bin/start passes an absolute path via AUDIT_FILE; default is .run/audit.log.
app.audit.file=${AUDIT_FILE:.run/audit.log}
-- Each pool member's cut for a closed or soft-closed period, fixed when it was closed: their cut
-- as it stood at that moment, keyed "pool-id:member-key" (member key p<person-id> or q<pool-id>).
-- A member with no cut then has no row. The rows go when the period is reopened.
CREATE TABLE period_pool_cut (
    period_id BIGINT         NOT NULL REFERENCES period (id),
    cut_key   VARCHAR(100)   NOT NULL,
    cut       DECIMAL(14, 2) NOT NULL,
    PRIMARY KEY (period_id, cut_key)
);
-- The sheet's history keeps them too, as text: "pool-id:member-key=cut", separated by ";".
ALTER TABLE period_revision ADD COLUMN pool_cuts VARCHAR(20000) DEFAULT '' NOT NULL;
-- The sheet's score log switch: on or off (blank), not dated. While it is on, changing the sheet's
-- today records each person's score on the day being left, before their snapshots.
ALTER TABLE sheet ADD COLUMN score_log BOOLEAN NOT NULL DEFAULT FALSE;
package net.officefloor.hq.app.period;

import jakarta.persistence.CollectionTable;
import jakarta.persistence.Column;
import jakarta.persistence.ElementCollection;
import jakarta.persistence.FetchType;
import jakarta.persistence.JoinColumn;
import jakarta.persistence.MapKeyColumn;
import jakarta.persistence.Entity;
import jakarta.persistence.GeneratedValue;
import jakarta.persistence.GenerationType;
import jakarta.persistence.Id;
import jakarta.persistence.Table;
import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.Map;

/** A period on a sheet: a named run of days from its from-date to its to-date, both inclusive. A
 *  claim belongs to the period whose days contain its due-by. A closed period keeps the due-total it
 *  had when it was closed, and no claim due by a day inside it can be changed. A soft-closed period
 *  keeps its due-total as a closed one does, but claims due inside it can still be added and changed. */
@Entity
@Table(name = "period")
public class Period {

    @Id
    @GeneratedValue(strategy = GenerationType.IDENTITY)
    private Long id;

    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Column(name = "name", nullable = false)
    private String name;

    @Column(name = "from_date", nullable = false)
    private LocalDate fromDate;

    @Column(name = "to_date", nullable = false)
    private LocalDate toDate;

    @Column(name = "closed", nullable = false)
    private boolean closed;

    @Column(name = "soft_closed", nullable = false)
    private boolean softClosed;

    @Column(name = "closed_total")
    private BigDecimal closedTotal;

    /** Whether a steward has locked the period: a locked period cannot be reopened. */
    @Column(name = "locked", nullable = false)
    private boolean locked;

    /** The most open or pending claims a person may have in the period; null for no cap. */
    @Column(name = "claim_cap")
    private Integer claimCap;

    /** Each person's due-total for the period, by the person's id, fixed when it was closed; empty
                : service.list(sheetId.trim());
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return periods.stream().map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public PeriodView add(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody PeriodForm form) {
        return view(sheetId.trim(), service.add(sheetId.trim(), user.trim(), form.name().trim(), form.from(), form.to(), form.cap()));
    }

    @PostMapping("/generate")
    public List<PeriodView> generate(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateForm form) {
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return service.generate(sheetId.trim(), user.trim(), form.from(), form.to()).stream()
                .map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping("/generate-fy")
    public List<PeriodView> generateFy(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateFyForm form) {
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return service.generateFiscalYear(sheetId.trim(), user.trim(), form.yearValue()).stream()
                .map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    /** What a rollover shows: how many periods it made, and every period it changed. */
    public record RolloverView(int made, List<PeriodView> periods) {
    }

    @PostMapping("/rollover")
    public RolloverView rollover(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateFyForm form) {
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        PeriodService.RolledOver done = service.rollover(sheetId.trim(), user.trim(), form.yearValue());
        return new RolloverView(done.made().size(),
                done.changed().stream().map(p -> PeriodView.of(p, fiscalStartMonth)).toList());
    }

    @PostMapping("/generate-quarters")
    public List<PeriodView> generateQuarters(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user,
            @Valid @RequestBody GenerateFyForm form) {
        int fiscalStartMonth = sheets.fiscalStartMonth(sheetId.trim());
        return service.generateQuarters(sheetId.trim(), user.trim(), form.yearValue()).stream()
                .map(p -> PeriodView.of(p, fiscalStartMonth)).toList();
    }

    @PostMapping("/{periodId}/close")
    public PeriodView close(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.close(sheetId.trim(), user.trim(), periodId));
    }

    @PostMapping("/{periodId}/soft-close")
    public PeriodView softClose(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.softClose(sheetId.trim(), user.trim(), periodId));
    }

    @PostMapping("/{periodId}/reopen")
    public PeriodView reopen(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.reopen(sheetId.trim(), user.trim(), periodId));
    }

    @PostMapping("/{periodId}/lock")
    public PeriodView lock(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.lock(sheetId.trim(), user.trim(), periodId, true));
    }

    @PostMapping("/{periodId}/unlock")
    public PeriodView unlock(@PathVariable @NotBlank @Size(max = 100) String sheetId,
            @RequestHeader("X-User") @NotBlank @Size(max = 100) String user, @PathVariable long periodId) {
        return view(sheetId.trim(), service.lock(sheetId.trim(), user.trim(), periodId, false));
    }
}
